def enhance(content):
    # A concise transition keeps the full 27-country map with the section opening.
    content,n=re.subn(r'^Изменение распределения между странами ЕС является самостоятельной стороной адаптации\.[^\n]+', 'Географический анализ отделяет перераспределение крупных потоков между действующими странами оформления от появления новых положительных направлений.',content,flags=re.M)
    assert n==1
    # Keep the long sensitivity-table source and its native footnote on one page.
    # The table already lists all seven variants for both outcomes and technologies.
    content,n=re.subn(r'^Источник: авторские расчёты\. Все семь вариантов приведены для обоих исходов и технологий;[^\n]+',
        lambda m:'Источник: расчёты автора. Опубликованные пары меняют наблюдаемость; полностью сбалансированная наблюдаемая панель без китайских HEV не образует дополнительной модели трёх технологий.'+''.join(re.findall(r'\[\^[^\]]+\]',m[0])),content,flags=re.M)
    assert n==1
    # Four separate readable panels replace the original dense appendix plot.
    def appendix(match):
        blocks=[]
        notes=''.join(re.findall(r'\[\^[^\]]+\]',match[0]))
        for i,(letter,name,cat,outcome)in enumerate([('а','a','PHEV','количество'),('б','b','PHEV','стоимость'),('в','c','HEV','количество'),('г','d','HEV','стоимость')]):
            cap='Рисунок А.3 — Чувствительность окончательных множителей к спецификации'if i==0 else 'Продолжение рисунка А.3'
            blocks.append(f'![{cat}, {outcome}](thesis_figures/G12_{name}.svg)\n\n{cap} — {letter}) {cat}, {outcome}\n\nИсточник: Eurostat Comext; расчёты автора. Все интервалы HAC(12). Основная спецификация выделена синим, отдельная дополнительная диагностика без NL — бирюзовым, остальные варианты — красным. Исключение NL меняет географический охват.'+(notes if i==0 else ''))
        return '\n\n'.join(blocks)
    content,n=re.subn(r'!\[[^\]]*\]\(chapter2_figures/G12_sensitivity\.svg\)\s*\n\nРисунок А\.3[^\n]+\n\nИсточник:[^\n]+',appendix,content)
    assert n==1
    content=re.sub(r'\]\(chapter2_figures/([^)]+)\)',r'](thesis_figures/\1)',content)
    content=re.sub(r'\]\(chapter3_figures/([^)]+)\)',r'](thesis_figures/C3_\1)',content)
    # Protect old caption numbers and prose references before new insertions.
    content=re.sub(r'(?i)(рисун(?:ок|ка|ке|ку|ком|ки|ков|ках)\s+)([123А])\.(\d+)',lambda m:m[1]+'[[FIG:O_'+m[2]+'_'+m[3]+']]',content)
    new_by_id={x[0]:x for x in NEW}
    for ident,chapter,anchor,title,source,lead in NEW:
        marker='[[FIG:N_'+ident+']]'
        block=lead.replace('{ref}',marker)+f'\n\n![{title}](thesis_figures/{ident}.svg)\n\nРисунок {marker} — {title}\n\nИсточник: {source}'
        if anchor.startswith('<!--'):
            assert content.count(anchor)==1,anchor
            content=content.replace(anchor,anchor+'\n\n'+block)
        else:
            pattern=r'^'+re.escape(anchor)+r'[^\n]*'
            content,n=re.subn(pattern,lambda m:m[0]+'\n\n'+block,content,flags=re.M)
            assert n==1,(ident,n)
    counts={};numbers={};catalog=[]
    pattern=r'^Рисунок \[\[FIG:([^\]]+)\]\] — ([^\n]+)'
    for match in re.finditer(pattern,content,re.M):
        key,title=match.groups()
        chapter=key.split('_')[1]if key.startswith('O_')else str(new_by_id[key[2:]][1])
        counts[chapter]=counts.get(chapter,0)+1;numbers[key]=chapter+'.'+str(counts[chapter])
        catalog.append({'number':numbers[key],'title':title,'key':key,'new':key.startswith('N_')})
    assert counts=={'1':3,'2':17,'3':7,'А':5},counts
    content=re.sub(r'\[\[FIG:([^\]]+)\]\]',lambda m:numbers[m[1]],content)
    assert '[[FIG:'not in content
    (HERE/'thesis_figures'/'placement_manifest.json').write_text(json.dumps({'date':'2026-10-28','logical_figures':len(catalog),'added':len(NEW),'by_chapter':counts,'figures':catalog,'old_to_new':{k[2:].replace('_','.'):v for k,v in numbers.items()if k.startswith('O_')}},ensure_ascii=False,indent=2)+'\n')
    rows=['# Каталог рисунков полного диплома','','| Номер | Название | Добавлен |','|---|---|---|']
    for item in catalog:
        title=item['title'].replace(' — а) PHEV, количество','')
        rows.append('| '+item['number']+' | '+title+' | '+('Да'if item['new']else'Нет, переоформлен')+' |')
    (HERE/'thesis_figures'/'illustration_catalog.md').write_text('\n'.join(rows)+'\n')
    return content
